// Sta je stiglo. Odavde krecu tvoja pravila.
//
// Sve sto ti treba je u `poruka`:
//   business_id      koji salon
//   customer_phone   ko pise (po ovome ga prepoznajemo)
//   text             sta je napisao
//   received_at      kada
//
// Ovdje mozes dodati vlastito skretanje prije nego sto asistent uopste
// odgovori. Primjer koji je odmah upotrebljiv:
//
//   const van = ['spam', 'reklama'];
//   if (van.some((r) => poruka.text.toLowerCase().includes(r))) {
//     return [{ json: { preskoci: true, poruka } }];
//   }

const poruka = $input.first().json;

return [{ json: { preskoci: false, poruka } }];

// Zadnja rijec je tvoja: ovdje mozes promijeniti tekst prije slanja.
//
// `odgovor.reply` je ono sto kupac dobija. `odgovor.intent` kaze o cemu se
// radilo (new_booking, cancel_booking, general_question ...).
//
// Primjer — dodaj potpis salona samo na potvrdu termina:
//
//   if (odgovor.intent === 'new_booking' && odgovor.booking?.appointmentId) {
//     odgovor.reply += '\n\nVidimo se! Salon Rezora';
//   }

const odgovor = $input.first().json;

return [{ json: odgovor }];

// Poruka je namjerno preskocena — asistent suti.
// Prazan `reply` gateway razumije kao "nema sta poslati".

return [{ json: { reply: '', duplicate: false, handoff: false, intent: 'unknown' } }];
